int test_file(const char* fname) {
    FILE *ifile;
    igraph_t g;
    int retval;

    ifile = fopen(fname, "r");
    if (ifile == 0) {
        return 1;
    }

    retval = igraph_read_graph_gml(&g, ifile);
    if (!retval) {
        /* input was accepted, this is a bug; attempt to clean up after
                 * ourselves nevertheless */
        igraph_destroy(&g);
        fclose(ifile);
        return 2;
    }

